
.character-list {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding-bottom: 80px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;

  .desc {
    font-size: 14px;
    color: #a1a1aa;
  }
}

.action-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  background: rgba(255, 255, 255, 0.05);
  color: #e4e4e7;

  &:hover {
    background: rgba(255, 255, 255, 0.1);
  }
}

:global(.light) .action-btn {
  background: rgba(0, 0, 0, 0.05);
  color: #27272a;

  &:hover {
    background: rgba(0, 0, 0, 0.1);
  }
}

.character-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;

  @media (min-width: 640px) {
    grid-template-columns: repeat(2, 1fr);
  }
}

.character-card {
  padding: 20px;
  border-radius: 16px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: all 0.2s;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.02);

  &:hover {
    border-color: rgba(255, 255, 255, 0.2);
  }

  &.protagonist {
    border-color: rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.03);
  }
}

:global(.light) .character-card {
  border-color: rgba(0, 0, 0, 0.1);
  background: #fff;

  &:hover {
    border-color: rgba(0, 0, 0, 0.2);
  }
}

.protagonist-badge {
  position: absolute;
  top: 0;
  right: 0;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 10px;
  padding: 4px 12px;
  border-bottom-left-radius: 8px;
  font-weight: 500;
  letter-spacing: 0.1em;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;

  .avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.05);
    color: #a1a1aa;
    transition: all 0.2s;

    i {
      font-size: 24px;
    }

    &.protagonist {
      background: rgba(255, 255, 255, 0.1);
      color: #fff;
    }

    &:not(.protagonist):hover {
      color: #e4e4e7;
    }
  }

  .info {
    h4 {
      font-size: 16px;
      font-weight: 500;
      color: #f4f4f5;
      margin-bottom: 4px;
    }

    p {
      font-size: 12px;
      color: #71717a;
    }
  }
}

:global(.light) .card-header {
  .avatar {
    background: rgba(0, 0, 0, 0.05);
    color: #71717a;

    &.protagonist {
      background: rgba(0, 0, 0, 0.1);
      color: #18181b;
    }
  }

  .info h4 {
    color: #18181b;
  }
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 8px;

  .stat-row {
    display: flex;
    justify-content: space-between;
    font-size: 12px;

    .label {
      color: #71717a;
    }

    .value {
      color: #d4d4d8;
      font-family: monospace;
    }
  }
}

:global(.light) .stats .stat-row .value {
  color: #27272a;
}
