
.rule-modifier {
  display: flex;
  width: 100%;
  max-width: 1200px;
  max-height: 700px; // 限制最大高度
  margin: 0 auto;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.5;

  &.dark {
    background: #030303;
    color: #f4f4f5;
  }

  &.light {
    background: #f4f4f5;
    color: #18181b;
  }
}

// Sidebar
.sidebar {
  width: 80px;
  max-height: 700px; // 限制最大高度
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.02);
  overflow: hidden;

  @media (min-width: 1024px) {
    width: 240px;
  }
}

.dark .sidebar {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .sidebar {
  border-color: rgba(0, 0, 0, 0.05);
  background: rgba(255, 255, 255, 0.6);
}

.sidebar-top {
  .logo {
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    gap: 12px;
    padding: 0 24px;

    i {
      font-size: 24px;
    }

    .logo-text {
      display: none;
      font-weight: 600;
      letter-spacing: 0.15em;
      font-size: 16px;

      @media (min-width: 1024px) {
        display: block;
      }
    }
  }

  .nav-items {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
}

.dark .sidebar-top .logo {
  border-color: rgba(255, 255, 255, 0.05);
  color: #f4f4f5;
}

.light .sidebar-top .logo {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;
}

.sidebar-bottom {
  padding: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.dark .sidebar-bottom {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .sidebar-bottom {
  border-color: rgba(0, 0, 0, 0.05);
}

.nav-btn {
  display: flex;
  align-items: center;
  padding: 12px;
  border-radius: 12px;
  transition: all 0.3s ease;
  position: relative;
  background: transparent;
  border: none;
  cursor: pointer;
  gap: 12px;
  width: 100%;

  i {
    font-size: 18px;
    width: 24px;
    text-align: center;
  }

  .nav-label {
    display: none;
    font-size: 14px;
    font-weight: 500;

    @media (min-width: 1024px) {
      display: block;
    }
  }

  &:hover {
    background: rgba(255, 255, 255, 0.05);
  }

  &.active {
    background: rgba(255, 255, 255, 0.1);

    .active-indicator {
      position: absolute;
      left: 0;
      width: 4px;
      height: 32px;
      background: currentColor;
      border-radius: 0 4px 4px 0;
    }
  }
}

.dark .nav-btn {
  color: #a1a1aa;

  &:hover {
    color: #e4e4e7;
    background: rgba(255, 255, 255, 0.05);
  }

  &.active {
    color: #fff;
    box-shadow: 0 0 15px rgba(255, 255, 255, 0.05);
  }
}

.light .nav-btn {
  color: #71717a;

  &:hover {
    color: #18181b;
    background: rgba(0, 0, 0, 0.05);
  }

  &.active {
    color: #000;
    background: rgba(0, 0, 0, 0.05);
    box-shadow: 0 0 15px rgba(0, 0, 0, 0.05);
  }
}

// Middle Panel
.middle-panel {
  width: 700px;
  max-height: 700px; // 限制最大高度
  flex-shrink: 0;
  overflow: hidden;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.3);
  z-index: 20;
  animation: slideIn 0.3s ease;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.dark .middle-panel {
  background: #080808;
  border-color: rgba(255, 255, 255, 0.05);
}

.light .middle-panel {
  background: #fff;
  border-color: rgba(0, 0, 0, 0.05);
}

.panel-inner {
  width: 700px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.panel-header {
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 40px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(255, 255, 255, 0.02);

  h1 {
    font-size: 24px;
    font-weight: 300;
    letter-spacing: 0.05em;
  }

  .close-btn {
    padding: 8px;
    border-radius: 50%;
    background: transparent;
    border: none;
    cursor: pointer;
    transition: all 0.2s;

    &:hover {
      background: rgba(255, 255, 255, 0.1);
    }
  }
}

.dark .panel-header {
  border-color: rgba(255, 255, 255, 0.05);
  color: #fff;

  .close-btn {
    color: #a1a1aa;

    &:hover {
      color: #fff;
    }
  }
}

.light .panel-header {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;
  background: rgba(255, 255, 255, 0.6);

  .close-btn {
    color: #71717a;

    &:hover {
      color: #18181b;
    }
  }
}

.panel-content {
  flex: 1;
  overflow-y: auto;
  padding: 24px 40px;
}

.fade-enter-active,
.fade-leave-active {
  transition: all 0.3s ease;
}

.fade-enter-from {
  opacity: 0;
  transform: translateY(15px);
}

.fade-leave-to {
  opacity: 0;
  transform: translateY(-15px);
}

// Main Panel
.main-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 10;
  overflow: hidden;
  max-height: 700px; // 限制最大高度
}

.dark .main-panel {
  background: #030303;
}

.light .main-panel {
  background: #fafafa;
}

.main-header {
  height: 80px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 32px;

  .header-title {
    display: flex;
    align-items: center;
    gap: 12px;

    i {
      font-size: 24px;
    }

    h2 {
      font-size: 18px;
      font-weight: 500;
      letter-spacing: 0.05em;
    }
  }
}

.dark .main-header {
  border-color: rgba(255, 255, 255, 0.05);

  .header-title {
    i { color: #d4d4d8; }
    h2 { color: #fff; }
  }
}

.light .main-header {
  border-color: rgba(0, 0, 0, 0.05);

  .header-title {
    i { color: #52525b; }
    h2 { color: #18181b; }
  }
}

.header-btn {
  background: transparent;
  border: none;
  font-size: 20px;
  cursor: pointer;
  transition: color 0.2s;
}

.dark .header-btn {
  color: #71717a;

  &:hover { color: #fff; }
}

.light .header-btn {
  color: #a1a1aa;

  &:hover { color: #18181b; }
}

.log-container {
  flex: 1;
  overflow-y: auto;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.input-area {
  padding: 24px 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.dark .input-area {
  background: rgba(0, 0, 0, 0.2);
  border-color: rgba(255, 255, 255, 0.05);
}

.light .input-area {
  background: rgba(255, 255, 255, 0.5);
  border-color: rgba(0, 0, 0, 0.05);
}

.input-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;

  textarea {
    width: 100%;
    border-radius: 16px;
    padding: 16px 64px 16px 24px;
    font-size: 16px;
    resize: none;
    outline: none;
    transition: all 0.2s;

    &:focus {
      box-shadow: 0 0 0 1px currentColor;
    }
  }
}

.dark .input-wrapper textarea {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #fff;

  &::placeholder { color: #52525b; }

  &:focus {
    border-color: rgba(255, 255, 255, 0.2);
  }
}

.light .input-wrapper textarea {
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.1);
  color: #18181b;

  &::placeholder { color: #a1a1aa; }

  &:focus {
    border-color: rgba(0, 0, 0, 0.2);
  }
}

.send-btn {
  position: absolute;
  bottom: 16px;
  right: 16px;
  padding: 12px;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 20px;
}

.dark .send-btn {
  background: rgba(255, 255, 255, 0.1);
  color: #d4d4d8;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.15);
  }
}

.light .send-btn {
  background: #18181b;
  color: #fff;

  &:hover {
    background: #27272a;
  }
}

// Modal
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(4px);
}

.modal-content {
  width: 100%;
  max-width: 600px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);

  &.modal-enter-active,
  &.modal-leave-active {
    transition: all 0.3s ease;
  }

  &.modal-enter-from,
  &.modal-leave-to {
    opacity: 0;
    transform: scale(0.95) translateY(20px);
  }
}

.dark .modal-content {
  background: #080808;
}

.light .modal-content {
  background: #fff;
  border-color: rgba(0, 0, 0, 0.1);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.02);

  h2 {
    font-size: 18px;
    font-weight: 500;
  }

  .close-btn {
    background: transparent;
    border: none;
    font-size: 20px;
    cursor: pointer;
    transition: color 0.2s;
  }
}

.dark .modal-header {
  border-color: rgba(255, 255, 255, 0.05);
  color: #fff;

  .close-btn {
    color: #71717a;

    &:hover { color: #fff; }
  }
}

.light .modal-header {
  border-color: rgba(0, 0, 0, 0.05);
  color: #18181b;

  .close-btn {
    color: #a1a1aa;

    &:hover { color: #18181b; }
  }
}

.modal-body {
  padding: 24px;
  min-height: 300px;
}

.modal-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 16px;
  height: 100%;

  .spin-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.05);
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(255, 255, 255, 0.1);

    i {
      font-size: 32px;
      color: #52525b;
    }
  }

  h3 {
    font-size: 16px;
    font-weight: 500;
    color: #e4e4e7;
  }

  p {
    font-size: 14px;
    color: #71717a;
    max-width: 300px;

    code {
      color: #d4d4d8;
      font-family: monospace;
    }
  }
}

.light .modal-placeholder {
  .spin-icon i { color: #a1a1aa; }
  h3 { color: #27272a; }
  p {
    color: #71717a;
    code { color: #52525b; }
  }
}

.modal-footer {
  padding: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.dark .modal-footer {
  border-color: rgba(255, 255, 255, 0.05);
}

.light .modal-footer {
  border-color: rgba(0, 0, 0, 0.05);
  background: rgba(0, 0, 0, 0.02);
}

.btn-secondary,
.btn-primary {
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}

.btn-secondary {
  color: #a1a1aa;
  background: transparent;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.05);
  }
}

.light .btn-secondary {
  color: #71717a;

  &:hover {
    color: #18181b;
    background: rgba(0, 0, 0, 0.05);
  }
}

.btn-primary {
  color: #fff;
  background: rgba(255, 255, 255, 0.15);

  &:hover {
    background: rgba(255, 255, 255, 0.2);
  }
}

.light .btn-primary {
  color: #fff;
  background: #18181b;

  &:hover {
    background: #27272a;
  }
}
